#!/usr/bin/env python3
import os


TO_REMOVE = [ 'build' ]
CWD       = os.getcwd()

# -------------------------------------------------------------------------------------------------------------------- #

def remove(_path):
  os.system(f'rm -rf {_path}')

# -------------------------------------------------------------------------------------------------------------------- #

for item in TO_REMOVE:
  path = os.path.join(CWD, item)
  remove(path)

# -------------------------------------------------------------------------------------------------------------------- #

def main():
  for root, dirs, files in os.walk(CWD):
    for dname in dirs:
      path = os.path.join(root, dname)
      remove(path)

# -------------------------------------------------------------------------------------------------------------------- #

if __name__ == '__main__':
  main()